const newsItems = $input.all();
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.usedLinks)) {
  staticData.usedLinks = [];
}
const usedLinks = new Set(staticData.usedLinks);

const unused = newsItems.filter(it => {
  const link = (it.json && (it.json.link || it.json.guid)) || '';
  return link && !usedLinks.has(link.trim());
});

if (unused.length === 0) {
  throw new Error('No unused articles found this week — all fetched RSS items have already been used. Add a new feed or wait for fresh articles.');
}

unused.sort((a, b) => {
  const da = new Date((a.json && (a.json.isoDate || a.json.pubDate)) || 0).getTime();
  const db = new Date((b.json && (b.json.isoDate || b.json.pubDate)) || 0).getTime();
  return db - da;
});

return unused;

const items = $input.all();
const chosen = items[0];
const j = chosen.json || {};
const title = j.title || 'Untitled';
const link = j.link || j.guid || '';
const summary = j.contentSnippet || j.content || j.summary || '';

return [{
  json: {
    newsBlock: title + (summary ? ('\n' + summary) : '') + (link ? ('\nSource: ' + link) : ''),
    topHeadline: title,
    articleLink: link,
  },
}];

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.usedLinks)) {
  staticData.usedLinks = [];
}

const link = $('Pick One Article').item.json.articleLink;
if (link && !staticData.usedLinks.includes(link)) {
  staticData.usedLinks.push(link);
}

if (staticData.usedLinks.length > 200) {
  staticData.usedLinks = staticData.usedLinks.slice(-200);
}

return [{ json: { markedUsed: link, totalTracked: staticData.usedLinks.length } }];

